def legal(title, intro, sections, name):
    body=f'<section class="text-hero section-pad legal-hero"><p class="eyebrow">TRASPARENZA E RISERVATEZZA</p><h1>{title}</h1><p>{intro}</p><p class="policy-date">Ultimo aggiornamento: 24 settembre 2026</p></section><article class="legal-copy section-pad">'+''.join(f'<section><h2>{h}</h2>{p}</section>' for h,p in sections)+'</article>'
    (ROOT/name).write_text(page(title,intro,body,name))

