def update_home():
    p=ROOT/'index.html'; text=p.read_text()
    text=text.replace('<html lang="it">','<html lang="it" id="top">')
    text=text.replace('assets/logo.svg','assets/logo-bianco.png')
    text=text.replace('LE NOSTRE SPECIALITÀ','I NOSTRI SERVIZI').replace('Le specialità','Servizi')
    text=text.replace('https://cdn.jsdelivr.net/npm/lenis@1.3.17/dist/lenis.min.js','assets/vendor/lenis.min.js')
    if 'href="site.css' not in text: text=text.replace('<link rel="stylesheet" href="style.css">','<link rel="stylesheet" href="style.css"><link rel="stylesheet" href="site.css">')
    if 'src="site.js"' not in text: text=text.replace('<script defer src="app.js"></script>','<script defer src="app.js"></script><script defer src="site.js"></script>')
    text=re.sub(r'<a class="skip".*?</a>','',text,count=1)
    text=re.sub(r'<header class="header">.*?</nav>\s*<main',header()+'\n<main',text,count=1,flags=re.S)
    text=text.replace('<main>','<main id="contenuto">')
    text=text.replace('href="#contatti"','href="contatti.html"').replace('href="https://foroischiatico.it/contatto/"','href="contatti.html"')
    text=text.replace('href="tel:+390756976891">Informazioni e appuntamenti','href="contatti.html">Informazioni e appuntamenti')
    text=text.replace('href="https://foroischiatico.it/diagnosi-e-valutazione/"','href="valutazione.html"')
    text=text.replace('href="https://foroischiatico.it/trattamento-di-posturologia-decompressiva-su-lettino-decompressivo-btl/"','href="servizi/posturologia-e-decompressione-spinale.html"')
    for s in SERVICES: text=text.replace('href="https://foroischiatico.it/'+s['slug']+'/"','href="servizi/'+s['slug']+'.html"')
    text=re.sub(r'<footer.*?</footer>',footer(),text,count=1,flags=re.S)
    if 'id="cookie-banner"' not in text: text=text.replace('</body>',cookies()+'\n</body>')
    p.write_text(text)

def assessment():
    body='''<section class="text-hero section-pad"><p class="eyebrow">LA VALUTAZIONE INIZIALE</p><h1>Prima di tutto,<br><em>conoscerti.</em></h1><p>Ogni percorso parte dall’ascolto: le tue esigenze, le attività quotidiane e gli obiettivi che desideri affrontare.</p></section><article class="legal-copy section-pad"><section><h2>Un punto di partenza condiviso</h2><p>La valutazione aiuta a comprendere la situazione e a definire quali approfondimenti o servizi siano appropriati. Il professionista considera le informazioni raccolte e il movimento, mettendoli in relazione con la tua storia.</p></section><section><h2>Competenze che dialogano</h2><p>Le analisi di postura, movimento e appoggio possono affiancarsi, quando indicato, alla valutazione specialistica. Non occorre scegliere da soli un trattamento: puoi iniziare chiedendo informazioni al centro.</p></section><section><h2>Organizziamo il primo incontro</h2><p>Indica lo studio che preferisci e un recapito. Il centro ti fornirà informazioni su disponibilità e modalità dell’appuntamento.</p><a class="button light" href="contatti.html">Richiedi una valutazione ↗</a></section></article>'''
    (ROOT/'valutazione.html').write_text(page('La valutazione iniziale','Ascolto e valutazione per definire il tuo percorso con Foro Ischiatico.',body,'valutazione.html'))

if __name__=='__main__':
    (ROOT/'servizi').mkdir(exist_ok=True)
    for service in SERVICES: service_page(service)
    contacts(); policies(); assessment(); update_home()
    print(f'Generated {len(SERVICES)} service pages, contact, policies and assessment; updated home.')
